mapper.update:
UPDATE playlist SET title = #{title}, description = #{description},
                    total_duration = #{totalDuration}, is_public = #{isPublic},
                    listen_minutes = #{listenMinutes}
WHERE id = #{id}

mapper.select:

WHERE p.user_id = #{userId}
ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit} OFFSET #{offset}

WHERE p.is_public = true
ORDER BY p.play_count DESC, p.created_at DESC, p.id DESC ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit} OFFSET #{offset}
